input.new_string:
  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that starts before and ends inside an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Before-Inside');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that contains an active booking entirely', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Contains');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects updating a booking to a conflicting start time', async () => {
    await book(24, 25);
    const second = await book(26, 27);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects updating a booking to a conflicting end time', async () => {
    await book(24, 25);
    const second = await book(26, 27);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { endsAt: inHours(24.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects updating a booking to a conflicting room', async () => {
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    const otherRoomId = other.json().id;
    await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId: otherRoomId,
        userId,
        title: 'Existing',
        startsAt: inHours(24),
        endsAt: inHours(25),
      },
    });
    const second = await book(26, 27);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { roomId: otherRoomId, startsAt: inHours(24.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('allows updating just the title even when times overlap with self', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { title: 'Updated Title' },
    });
    expect(response.statusCode).toBe(200);
    expect(response.json().title).toBe('Updated Title');
  });
});

