// Demonstração do bug que foi corrigido

console.log("=== DEMONSTRAÇÃO DA CORREÇÃO ===\n");

const HOUR = 3_600_000;

function inHours(hours) {
  return new Date(Date.now() + hours * HOUR).toISOString();
}

// Simulando dois horários
const existing = { startsAt: new Date(Date.now() + 24 * HOUR), endsAt: new Date(Date.now() + 25 * HOUR) };
const newBooking1 = { startsAt: new Date(Date.now() + 23.5 * HOUR), endsAt: new Date(Date.now() + 24.5 * HOUR) };
const newBooking2 = { startsAt: new Date(Date.now() + 23 * HOUR), endsAt: new Date(Date.now() + 26 * HOUR) };

console.log("Reserva existente: 24:00 - 25:00\n");

console.log("Cenário 1: Nova reserva 23:30 - 24:30 (começa antes, termina dentro)");
console.log("Esperado: CONFLITO ✓");
const conflict1 = existing.startsAt < newBooking1.endsAt && newBooking1.startsAt < existing.endsAt;
console.log("Resultado: " + (conflict1 ? "CONFLITO ✓" : "SEM CONFLITO ✗") + "\n");

console.log("Cenário 2: Nova reserva 23:00 - 26:00 (contém completamente)");
console.log("Esperado: CONFLITO ✓");
const conflict2 = existing.startsAt < newBooking2.endsAt && newBooking2.startsAt < existing.endsAt;
console.log("Resultado: " + (conflict2 ? "CONFLITO ✓" : "SEM CONFLITO ✗") + "\n");

console.log("A lógica corrigida agora verifica:");
console.log("  startsAt: { lt: novaEndsAt }  → reserva começa ANTES de nova terminar");
console.log("  endsAt: { gt: novaStartsAt }  → reserva termina DEPOIS de nova começar");
console.log("\nIsso detecta qualquer sobreposição (início, fim, contém, está contida).");
EOF
node /tmp/test-conflict-manual.mjs

